import{_ as o,l as i,o as e,c as n,v as t,p as c,x as s,d as l,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"崩溃一致性","description":"","frontmatter":{"title":"崩溃一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/crash-consistency.md","filePath":"cs/crash-consistency.md","lastUpdated":1789023840000}'),E={name:"cs/crash-consistency.md"};function p(f,a,_,A,m,u){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="崩溃一致性" tabindex="-1">崩溃一致性 <a class="header-anchor" href="#崩溃一致性" aria-label="Permalink to &quot;崩溃一致性&quot;">​</a></h1><div class="epigraph"><p>崩溃后文件系统应回到某个过去的一致切面：无悬挂指针、无重复分配；可以丢最近未提交的更新。</p><footer>—— 据 Chidambaram 等对崩溃一致性的表述；McKusick；ext4 文档整理</footer></div><p><a href="/cs/ext4-journal">上一课</a>用日志实现了一种切面。<a href="/cs/fsync">fsync</a> 把切面推到「这一文件」。缺口是<strong>规格</strong>：应用程序可以指望什么（POSIX 很弱），文件系统实际提供什么（元数据一致、可选数据 ordered），以及 fsck、写时复制 FS、软更新如何对照——合并进一课，不当三篇词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一致：每个块最多属于一个 inode 或空闲，目录项指向已分配 inode，链接计数对得上。持久：fsync 过的应还在。POSIX 几乎不保证未 fsync 的 <code>write</code>。缺口：教学上分开「元数据一致」与「数据相对元数据的顺序」。日志、软更新（按依赖排写回）、写时复制（新树切换根指针）都是实现同一规格的手段。本课不把每篇 FAST 论文列成清单。</p><p><span class="marginnote">fsck 是离线修补；日志把 fsck 变成重放。COW 文件系统用原子根更新，仍要写回顺序与校验。 Barb 掉电不是本课实验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规格：恢复后元数据图合法；ordered 日志下，若新文件名可见则数据块不是旧泄露（在实现正确时）。应用要跨崩溃的文件内容，必须 fsync 数据再 fsync 目录。内核：提交事务或切换树根。对照 <a href="/cs/wal">WAL</a>：数据库可在文件已一致的前提下再保证元组；OS 课不重写 REDO。</p>',8)),(e(),c(h,null,{default:s(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20REPLAY%5B%22%E9%87%8D%E6%94%BE%E6%97%A5%E5%BF%97%E6%88%96%E5%88%87%E5%88%B0%E6%97%A7%E6%A0%B9%22%5D%0A%20%20REPLAY%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E5%9B%BE%E5%90%88%E6%B3%95%22%5D%0A%20%20META%20--%3E%20LOST%5B%22%E6%9C%AA%E6%8F%90%E4%BA%A4%E6%9B%B4%E6%96%B0%E5%8F%AF%E4%B8%A2%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>崩溃一致性是延迟写的对价：性能来自乱序与批量，正确性来自「可指出的切面」。没有切面就只能 fsck 猜。本课把 ext4 从机制升到义务，后面的权限课假定盘上对象在恢复后仍是那个 inode。不要写利用不一致的攻击步骤。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每个云盘同步语义。不保证虚拟机宿主机崩溃等于客机 fsync 完成——那是 virtio 以后的问题。下一课离开一致性，看 inode 上的模式位：谁被允许读这个已恢复的文件。</p><p>后课默认：恢复后有合法 inode。用户/组/其它的 rwx 如何编码，下一课模式位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>崩溃后要元数据图合法；未提交更新可丢。</li><li>日志、软更新、COW 是实现切面的手段。</li><li>访问控制位是下一课。</li><li>出处：POSIX 持久语义；McKusick；Linux ext4 文档；崩溃一致性文献的教学整理。</li></ul>',7))])}const x=o(E,[["render",p]]);export{T as __pageData,x as default};
